-- ============================================================================
-- Fooday — import real catalog migrated from Firestore (collection=dish,
-- doc=restaurant). Generated by ~/fooday-migration/transform.cjs.
-- Run in Supabase Dashboard → SQL Editor (idempotent on slug).
-- ============================================================================

-- 1. lossless columns for fields foods did not have
alter table public.foods add column if not exists address text;
alter table public.foods add column if not exists opening_time text;
alter table public.foods add column if not exists review_note text;

-- 2. replace mode: remove the 14 demo seed dishes (cascades their favorites)
delete from public.foods where slug in ('spicy-beef-ramen', 'classic-beef-burger', 'crispy-fried-chicken', 'rainbow-poke-bowl', 'wood-fired-pizza', 'salmon-sushi-platter', 'garden-buddha-bowl', 'grilled-herb-plate', 'iced-matcha-latte', 'mixed-berry-smoothie', 'fresh-orange-juice', 'caramel-latte', 'choco-chip-cookies', 'glazed-donuts');

-- 3. insert 94 migrated dishes
on conflict (slug) do nothing;
